  function restoreDraft(){const value=drafts.get(draftKey())||{};draft=value.draft||'';attachments=structuredClone(value.attachments||[]);pending=value.pending||null;taskPending=value.taskPending||null;mode=value.mode||'chat';recipient=value.recipient||'all';summarize=value.summarize!==false;$('#chatText').value=draft;$('#chatMode').value=mode;drawAttachments();drawRecipients();}
  function setHtml(node,html){if(node&&node.dataset.rendered!==html){node.innerHTML=html;node.dataset.rendered=html;}}
