    $('#chatCurrentModel').textContent=mode==='task'?'按当前分工协作':team?'总控 '+contactName(lead):current?contactName(current):'尚未选择';$('#chatCurrentModel').title=mode==='task'?(main?.model||''):team?(lead?.model||''):(current?.model||'');const preview=$('#chatTeamPreview');if(preview){const ids=mode==='task'?[...new Set(window.TeamUI.roles.map(([role])=>window.TeamUI.resolve(config,role)?.id).filter(Boolean))]:team?chat.participantIds:direct?[chat.directProviderId]:providers.map(p=>p.id);setHtml(preview,ids.slice(0,4).map(id=>{const p=providers.find(p=>p.id===id);return `<span title="${esc((p?.name||'已移除')+' · '+(p?.model||''))}">${avatar(p)}</span>`;}).join('')+(ids.length>4?`<small>+${ids.length-4}</small>`:''));}
