    setHtml(roster,mode==='task'?window.TeamUI.roster(config,main?.id):(team||direct)?window.TeamUI.conversationRoster(chat,config):window.TeamUI.roster(config,selected));roster.scrollLeft=scroll;
    const missing=window.TeamUI.roles.filter(([role])=>!window.TeamUI.resolve(config,role));
