  function paintMessages(target,messages){delete target.dataset.rendered;
    const key=chat?.id||'new';renderer.begin(key);const ids=new Set(),groupIds=new Set(),children=[];
    const last=messages.filter(m=>m.role==='user').at(-1)?.requestId;
    const nodeFor=message=>{ids.add(message.id);const stamp=JSON.stringify([message,folds.replies.get(replyKey(message)),message.requestId===last,message.requestId===last&&chat?.status,providers.find(p=>p.id===message.providerId)?.name]);return renderer.message(message,stamp,()=>messageHtml(message,messages));};
    const handled=new Set();
    for(const message of messages){
      const summary=chat?.kind==='team'&&messages.find(m=>m.requestId===message.requestId&&m.purpose==='summary');
      if(!summary){children.push(nodeFor(message));continue;}
      if(handled.has(message.requestId))continue;
      if(message.role!=='user'){children.push(nodeFor(message));continue;}
      handled.add(message.requestId);children.push(nodeFor(message),nodeFor(summary));
      const members=messages.filter(m=>m.requestId===message.requestId&&m.purpose==='discussion'),finished=members.filter(m=>m.status==='completed').length,failed=members.filter(m=>['failed','interrupted'].includes(m.status)).length;
      const retry=message.requestId===last&&chat.status!=='running'&&messages.some(m=>m.requestId===last&&m.role==='assistant'&&['failed','interrupted'].includes(m.status)&&!m.retryBlocked),stopped=members.some(m=>m.error==='你已停止这轮回复。');
      groupIds.add(message.requestId);children.push(renderer.group(message.requestId,'<strong>模型输出</strong><span>'+finished+' / '+members.length+' 已完成'+(failed?' · '+failed+' 未完成':'')+'</span>',members.map(nodeFor),retry?'<div class="chat-round-retry"><span>成功回复已保留，只重试未完成的部分。</span><button type="button" data-retry-message="'+esc(message.requestId)+'">'+(stopped?'继续未完成的回复':'重试未完成')+'</button></div>':''));
    }
    if(chat?.jobIds?.length){const holder=document.createElement('div');holder.className='chat-job-list';holder.innerHTML=taskCards();for(const node of [...holder.children]){const old=target.querySelector('[data-chat-job="'+CSS.escape(node.dataset.chatJob)+'"]');if(old){renderer.morph(old,node);children.push(old);}else children.push(node);}}
    renderer.commit(target,children,ids,groupIds);
  }
  function acceptChat(next){if(!next)return;const current=chat?.streamVersion,incoming=next.streamVersion;if(current&&incoming&&chat?.id===next.id&&current.epoch===incoming.epoch&&incoming.seq<current.seq)return;chat=next;}
  function scheduleMessages(){if(renderFrame!==null)return;renderFrame=requestAnimationFrame(()=>{renderFrame=null;drawMessages();});}
  function updateScrollIndicator(){const target=$('#chatMessages'),button=$('#chatScrollBottom');if(!target||!button)return;const away=target.scrollHeight-target.scrollTop-target.clientHeight>120;if(!away)newContent=false;button.hidden=!away;button.textContent=newContent?'有新回复 ↓':'回到底部 ↓';}
  function drawMessages(){const target=$('#chatMessages');if(!target)return;$('.chat-room').dataset.chatKind=chat?.kind||'legacy';const nearBottom=target.scrollHeight-target.scrollTop-target.clientHeight<100;const messages=[...(chat?.messages||[])];if(optimistic&&optimistic.chatId===(chat?.id||'new')&&!messages.some(m=>m.role==='user'&&m.requestId===optimistic.requestId))messages.push(optimistic);const identity=chat?.id||'new';if(renderedChat!==identity){renderedChat=identity;announced=new Map(messages.map(m=>[m.id,m.status]));newContent=false;lastContent='';}const contentKey=messages.map(m=>m.id+':'+m.status+':'+m.text?.length).join('|');if(lastContent&&contentKey!==lastContent&&!nearBottom)newContent=true;lastContent=contentKey;
    if(messages.length||chat?.jobIds?.length)paintMessages(target,messages);else {renderer.reset();setHtml(target,chat?.kind==='team'?`<div class="chat-welcome group-welcome"><div class="welcome-mark">👥</div><span class="chat-greeting">团队已就位</span><h1>想让团队帮你做什么？</h1><p>直接说需求，总控会汇总各模型的回复。</p><div class="group-privacy-note">单聊记录不会自动带入群聊。成员的输出可在汇总下方展开查看。</div></div>`:chat?.kind==='direct'?`<div class="chat-welcome direct-welcome">${avatar(providers.find(p=>p.id===chat.directProviderId))}<span class="chat-greeting">单独聊聊</span><h1>${esc(providers.find(p=>p.id===chat.directProviderId)?.name||'模型已移除')}</h1><p>这里的消息只发送给这位 AI。点击左侧其他联系人，即可切换独立对话。</p></div>`:welcomeHtml());};drawTeam();drawRecipients();el.querySelectorAll('[data-chat-mode]').forEach(button=>button.disabled=sending);if($('#chatCreateTeam'))$('#chatCreateTeam').disabled=sending||teamStarting;if($('#chatChooseTeam'))$('#chatChooseTeam').disabled=sending||teamStarting;['#chatText','#chatAddImage','#chatAddLink','#chatFiles','#chatMode'].forEach(id=>{if($(id))$(id).disabled=sending;});$('#chatModelTrigger').disabled=sending||chat?.kind==='direct';target.closest('.chat-room')?.querySelectorAll('[data-remove-attachment]').forEach(button=>button.disabled=sending);
    $('#chatSend').disabled=!!navigating||sending||chat?.status==='running';$('#chatSend').textContent=chat?.status==='running'?'回复中…':sending?'正在开始…':mode==='task'?'开始 ↑':'发送 ↑';$('#chatTransfer').disabled=sending||!messages.some(m=>m.role==='user');
    if($('#chatStop')){$('#chatStop').hidden=chat?.status!=='running';$('#chatStop').disabled=stopping;$('#chatStop').textContent=stopping?'正在停止…':'停止回复 ■';$('#chatSend').hidden=chat?.status==='running';}
    if($('#chatDelete'))$('#chatDelete').disabled=!chat||sending||chat.status==='running';
    waitNodes.clear();target.querySelectorAll('[data-reply-started]').forEach(node=>waitNodes.add(node));if(waitNodes.size&&!waitClock)waitClock=setInterval(updateWaitDurations,1000);if(!waitNodes.size&&waitClock){clearInterval(waitClock);waitClock=null;}const finished=messages.filter(m=>m.role==='assistant'&&announced.get(m.id)==='pending'&&['completed','failed','interrupted'].includes(m.status));for(const m of messages)announced.set(m.id,m.status);if(finished.length&&$('#chatAnnouncer'))$('#chatAnnouncer').textContent=finished.length===1?(finished[0].providerName||'AI')+(finished[0].status==='completed'?' 回复完成':' 回复已结束'):finished.length+' 个模型的回复已更新';
    updateWaitDurations();if(!messages.length&&!chat?.jobIds?.length)target.scrollTop=0;else if(nearBottom)target.scrollTop=target.scrollHeight;updateScrollIndicator();const title=$('#chatRoomTitle');if(title)title.textContent=chat?.title||'新对话';
  }
  function drawAttachments(){if($('#chatAttachments'))$('#chatAttachments').innerHTML=attachmentHtml(attachments,true);}
  async function refreshModels(){let status=await api('/api/chat-status'+(chat?'?chatId='+encodeURIComponent(chat.id):''));if(!status?.config)status=await api('/api/status');providers=status.config.providers||[];jobs=status.jobs||[];approvals=status.approvals||[];teamConfig=status.config.agentProviders||{};drawModels();drawTeam();}
  async function refreshList(append=false){const data=await api('/api/chats'+(showArchived||append?'?'+(showArchived?'archived=1&':'')+(append?'offset='+nextHistory:''):''));chats=append?[...chats,...data.chats]:data.chats;nextHistory=data.next??null;drawList();}

  function stopPoll(){clearTimeout(polling);polling=null;clearTimeout(jobTimer);jobTimer=null;live?.close();live=null;liveId='';}
  function activeJob(){return (chat?.jobIds||[]).some(id=>!jobs.find(j=>j.id===id)||['running','queued','awaiting_approval'].includes(jobs.find(j=>j.id===id)?.status));}
  function pollJobs(){clearTimeout(jobTimer);jobTimer=null;if(!chat||!activeJob())return;const id=chat.id;jobTimer=setTimeout(async()=>{try{await refreshModels();if(chat?.id===id){drawMessages();pollJobs();}}catch{if(chat?.id===id)pollJobs();}},2500);}
  function fallbackPoll(){clearTimeout(polling);if(!chat||(chat.status!=='running'&&!activeJob()))return;const id=chat.id;polling=setTimeout(async()=>{try{const data=await api('/api/chats/'+id);if(chat?.id!==id)return;acceptChat(data.chat);drawMessages();if(chat.status!=='running')await refreshList();fallbackPoll();}catch{if(chat?.id===id){error('连接暂时中断，正在同步已发送消息；不会重复生成。');fallbackPoll();}}},1200);}
  function poll(){
    if(!chat||document.body.dataset.view!=='chat')return;pollJobs();
    if(fallback){fallbackPoll();return;}
    if(live&&liveId===chat.id)return;
    live?.close();const id=chat.id,mine=generation;liveId=id;
    live=window.ChatStream.watch(id,{
      onState(state){if(chat?.id!==id||mine!==generation)return;const note=$('#chatSyncState');if(note){note.textContent=state==='reconnecting'?'连接暂时中断，正在重新同步…':'';note.hidden=state!=='reconnecting';}},
      onFallback(){if(chat?.id!==id||mine!==generation)return;fallback=true;live=null;liveId='';fallbackPoll();},
      onEvent(event,data){
        if(chat?.id!==id||mine!==generation)return;
        if(event==='deleted'){stopPoll();newChat();refreshList().catch(()=>{});return;}
        if(event==='snapshot')acceptChat(data.chat);
        else if(event==='patch'){
          const version=chat.streamVersion;if(version?.epoch!==data.epoch||data.seq<=(version?.seq||0))return;
          const byId=new Map(chat.messages.map(message=>[message.id,message]));
          for(const update of data.messages){const prior=byId.get(update.id),next={...prior,...update};if('textDelta'in update){next.text=(prior?.text||'')+update.textDelta;delete next.textDelta;}byId.set(update.id,next);}
          for(const removed of data.removed)byId.delete(removed);
          chat={...chat,...data.meta,messages:data.order.map(key=>byId.get(key)).filter(Boolean),streamVersion:{epoch:data.epoch,seq:data.seq}};
        }else return;
        scheduleMessages();
        if(chat.status!=='running')refreshList().catch(()=>{});
      }
    });
  }
