  async function startTeam(){if(sending||teamStarting)return;teamStarting=true;const mine=++generation;navigating=mine;stopPoll();drawMessages();try{await refreshModels();if(mine!==generation)return;const ready=providers.filter(usable).slice(0,12);if(ready.length<2){error('连接至少两个模型，就可以一起群聊。');await window.RuntimeUI.openSettings();return;}const preferred=window.TeamUI?.resolve({providers,agentProviders:teamConfig},'orchestrator')?.id,data=await api('/api/chats',{kind:'team',participantIds:ready.map(p=>p.id),leadProviderId:ready.some(p=>p.id===preferred)?preferred:ready[0].id,reuse:true});if(mine!==generation)return;await openChat(data.chat.id);await refreshList();}catch(e){error(e.message);}finally{teamStarting=false;if(navigating===mine)navigating=0;drawMessages();poll();}}
