    input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>40*1024*1024)throw new Error('会话文件超过 40 MB');const data=await api('/api/chats/import',JSON.parse(await file.text()),60000);showArchived=true;await refreshList();await openChat(data.chat.id);window.Gongming?.toast('会话已导入归档，可移回最近会话继续。');}catch(e){window.Gongming?.toast(e.message);}finally{input.value='';}};importButton.onclick=()=>input.click();tools.append(importButton,input);
