  async function render(){if(!el){el=document.getElementById('chatView');el.innerHTML=`<div class="chat-shell"><aside class="chat-history"><div><h2>对话</h2><button class="icon-btn" id="chatNew" aria-label="新对话">＋</button></div><button type="button" class="chat-team-entry" id="chatCreateTeam"><span>👥</span><span>团队群聊</span><b>↗</b></button><details id="chatContactsSection" class="chat-contacts-section" ${folds.section?'open':''}><summary>AI 联系人 <span>单独聊</span></summary><div id="chatContacts"></div></details><div class="chat-recents-label">最近会话 <span id="chatRecentCount"></span></div><div id="chatList"></div><button class="text-link" id="chatSubscription">订阅与编码工具 ↗</button></aside><section class="chat-room"><header class="chat-room-head"><div><button type="button" id="chatSidebarToggle" aria-label="显示对话列表">☰</button><span id="chatRoomTitle">新对话</span></div><div class="button-row"><button class="text-link" id="chatDelete" aria-label="删除当前对话">删除对话</button><button class="outline-button" id="chatTransfer">交给总控</button></div></header><section class="conversation-team" aria-label="本机模型与协作分工"><div class="conversation-team-top"><div><strong id="chatTeamSummary">你的协作团队</strong><span id="chatTeamPreview" class="chat-team-preview"></span><span class="team-current">当前对话 · <b id="chatCurrentModel">尚未选择</b></span></div><div><button type="button" data-team-settings>调整分工</button><button type="button" id="chatTeamToggle" aria-controls="chatTeamRoster" aria-expanded="false">查看分工</button></div></div><div id="chatTeamRoster" class="conversation-team-roster"></div><p id="chatTeamNote" class="team-settings-note"></p></section><div id="chatMessages" class="chat-messages" role="log" aria-live="off"></div><button type="button" id="chatScrollBottom" class="chat-scroll-bottom" hidden>回到底部 ↓</button><div id="chatAnnouncer" class="sr-only" role="status" aria-live="polite" aria-atomic="true"></div><p id="chatSyncState" class="chat-sync-state" role="status" hidden></p><div class="chat-composer-wrap"><div id="chatError" role="alert"></div><form id="chatForm" class="chat-composer"><div id="chatRecipients" class="chat-recipients" hidden><div><label>发送给 <select id="chatRecipient" aria-label="选择群聊发言成员"><option value="all">@ 所有成员</option></select></label><label class="chat-summary-toggle"><input type="checkbox" id="chatSummarize" checked> 主模型汇总</label></div><small id="chatRequestHint"></small></div><div id="chatAttachments" class="chat-attachments"></div><textarea id="chatText" rows="3" maxlength="20000" aria-label="消息" placeholder="随便聊聊，或者说说你想做什么…"></textarea><div class="chat-composer-tools"><div><details class="chat-attach-menu" id="chatAttachMenu"><summary aria-label="添加图片或链接" title="添加图片或链接">＋</summary><div><button type="button" id="chatAddImage">添加图片</button><button type="button" id="chatAddLink">添加链接</button></div></details><div id="chatModeSwitch" class="chat-mode-switch" role="group" aria-label="工作方式"><button type="button" data-chat-mode="chat" aria-pressed="true">聊天</button><button type="button" data-chat-mode="task" aria-pressed="false">交给总控</button></div><select id="chatMode" class="native-model-select" aria-label="工作方式" tabindex="-1" aria-hidden="true"><option value="chat">聊天</option><option value="task">总控协作</option></select><input id="chatFiles" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden><select id="chatModel" class="native-model-select" aria-label="选择对话模型" tabindex="-1" aria-hidden="true"></select><div class="model-picker-wrap"><button type="button" id="chatModelTrigger" class="model-picker-trigger" aria-haspopup="listbox" aria-expanded="false"><span>选择模型</span>⌄</button><div id="chatModelPicker" class="model-picker" hidden><header>已连接模型 · 选择当前对话使用的版本</header><div id="chatModelOptions" class="model-picker-list" role="listbox" aria-label="选择模型"></div><button type="button" class="picker-manage" id="chatPickerManage">＋ 添加或管理连接</button></div></div><button type="button" id="chatConnect" aria-label="管理模型">连接模型</button></div><button type="button" id="chatVoice" aria-label="语音输入" title="语音输入"><svg viewBox="0 0 24 24"><rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/></svg></button><button id="chatSend" type="submit">发送 ↑</button></div></form><p id="chatModeHint" class="chat-mode-hint"></p><p class="chat-footnote">Shift + Enter 换行 · 内容保存在本机</p></div></section></div>`;
      $('#chatContactsSection').addEventListener('toggle',event=>{folds.section=event.currentTarget.open;rememberFolds();});$('#chatText').value=draft;$('#chatTeamToggle').onclick=()=>{teamExpanded=!teamExpanded;try{localStorage.setItem('gongming.chat.team-expanded',String(teamExpanded));}catch{}drawTeam();};$('#chatNew').onclick=newChat;$('#chatCreateTeam').onclick=startTeam;$('#chatRecipient').onchange=e=>{recipient=e.target.value;pending=null;drawRecipients();};$('#chatSummarize').onchange=e=>{summarize=e.target.checked;pending=null;drawRecipients();};$('#chatForm').onsubmit=e=>{e.preventDefault();submit();};$('#chatText').oninput=e=>{draft=e.target.value;pending=null;taskPending=null;};$('#chatText').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submit();}};$('#chatText').onpaste=e=>{const files=[...e.clipboardData.items].filter(i=>i.kind==='file').map(i=>i.getAsFile());if(files.length){e.preventDefault();addImages(files);}};$('#chatAddImage').onclick=()=>{$('#chatAttachMenu').open=false;$('#chatFiles').click();};$('#chatFiles').onchange=e=>{addImages([...e.target.files]);e.target.value='';};$('#chatAddLink').onclick=()=>{$('#chatAttachMenu').open=false;addLink();};$('#chatMode').onchange=e=>setMode(e.target.value);$('#chatSidebarToggle').onclick=()=>document.body.classList.toggle('chat-sidebar-open');$('#chatModel').onchange=e=>{if(['direct','team'].includes(chat?.kind)){drawModels();return;}selected=e.target.value;pending=null;drawPicker();drawTeam();};$('#chatModelTrigger').onclick=()=>togglePicker();$('#chatPickerManage').onclick=()=>{togglePicker(false);window.RuntimeUI.openSettings();};$('#chatModelOptions').onclick=e=>{const button=e.target.closest('[data-pick-model]');if(!button||['direct','team'].includes(chat?.kind))return;selected=button.dataset.pickModel;$('#chatModel').value=selected;pending=null;drawPicker();drawTeam();togglePicker(false);$('#chatModelTrigger').focus();};$('#chatModelPicker').onkeydown=e=>{const buttons=[...$('#chatModelOptions').querySelectorAll('button')];if(e.key==='Escape'){togglePicker(false);$('#chatModelTrigger').focus();}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const index=buttons.indexOf(document.activeElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}};$('#chatConnect').onclick=()=>window.RuntimeUI.openSettings();$('#chatSubscription').onclick=()=>window.RuntimeUI?.openSettings({category:'subscription'});$('#chatTransfer').onclick=transfer;
      $('#chatDelete').onclick=()=>deleteChat();$('#chatScrollBottom').onclick=()=>{$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;newContent=false;updateScrollIndicator();};$('#chatMessages').addEventListener('scroll',updateScrollIndicator,{passive:true});
      const stopButton=document.createElement('button');stopButton.id='chatStop';stopButton.type='button';stopButton.hidden=true;stopButton.textContent='停止回复 ■';stopButton.onclick=stopReply;$('#chatSend').before(stopButton);
      el.addEventListener('click',async event=>{const button=event.target.closest('[data-chat-copy-code]');if(!button)return;const code=button.closest('.chat-code-block')?.querySelector('pre code');if(!code)return;try{await copyText(code.textContent);button.textContent='已复制';setTimeout(()=>{if(button.isConnected)button.textContent='复制代码';},1800);}catch(e){error(e.message);}});
      el.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.chatQuestion){const job=jobs.find(item=>item.id===b.dataset.chatQuestion);if(job){$('#chatText').value=job.brief;draft=job.brief;setMode('chat');saveDraft();}return;}if(b.dataset.chatResume){resumeJob(b.dataset.chatResume);return;}if(b.dataset.chatEdit){editMessage(b.dataset.chatEdit);return;}if(b.dataset.chatRegenerate){regenerateMessage(b.dataset.chatRegenerate);return;}if(b.dataset.chatVersion){chooseVersion(b.dataset.chatVersion,Number(b.dataset.versionIndex));return;}if(b.dataset.chatQuote){const message=chat?.messages.find(m=>m.id===b.dataset.chatQuote);if(message){const quote=message.text.slice(0,3000).split('\n').map(line=>'> '+line).join('\n');$('#chatText').value=(draft?draft+'\n\n':'')+'引用 '+(message.role==='user'?'我':message.providerName||'AI')+' 的消息：\n'+quote+'\n\n';draft=$('#chatText').value;$('#chatText').focus();saveDraft();}return;}if(b.dataset.chatMode){setMode(b.dataset.chatMode);return;}if(b.dataset.foldReply){const message=chat?.messages.find(m=>m.id===b.dataset.foldReply);if(message){folds.replies.set(replyKey(message),b.getAttribute('aria-expanded')==='true');rememberFolds();drawMessages();[...el.querySelectorAll('[data-fold-reply]')].find(node=>node.dataset.foldReply===message.id)?.focus();}return;}if(b.dataset.chatId)openChat(b.dataset.chatId);if(b.dataset.directProvider)openDirect(b.dataset.directProvider);if(b.dataset.removeAttachment!==undefined&&!sending){attachments.splice(Number(b.dataset.removeAttachment),1);pending=null;drawAttachments();}if(b.dataset.retryMessage)submit(b.dataset.retryMessage);if(b.dataset.chatTask){$('#chatText').value=b.dataset.chatTask;setMode('task');}if(b.dataset.chatPrompt){setMode('chat');$('#chatText').value=b.dataset.chatPrompt;$('#chatText').focus();}if(b.dataset.chatResult)window.WorkflowsUI?.openResult(b.dataset.chatResult);if(b.dataset.chatApproval)openApproval(b.dataset.chatApproval);if(b.dataset.chatJobDetails)window.Gongming?.openView('runtime');if(b.dataset.copyMessage){const m=chat.messages.find(m=>m.id===b.dataset.copyMessage||m.requestId===b.dataset.copyMessage&&m.role==='assistant');navigator.clipboard.writeText(m?.text||'').then(()=>window.Gongming.toast('已复制')).catch(()=>error('无法复制，请手动选择文本'));}});
      const sidebar=document.querySelector('.sidebar');if(sidebar){historyEl=el.querySelector('.chat-history');historyEl.querySelector('h2').textContent='聊天';sidebar.append(historyEl);historyEl.addEventListener('click',historyClick);historyEl.addEventListener('contextmenu',historyContextMenu);historyEl.addEventListener('keydown',event=>{if(event.key==='ContextMenu'||(event.shiftKey&&event.key==='F10'))historyContextMenu(event);});const settings=document.createElement('button');settings.className='text-link chat-sidebar-settings';settings.dataset.action='settings';settings.textContent='工作台设置';historyEl.append(settings);simplifySidebar(sidebar,historyEl,settings);sidebar.querySelector('.new-task')?.addEventListener('click',()=>newChat());}
    }
    try{await Promise.all([refreshModels(),refreshList()]);if(!chat&&savedId){const id=savedId;savedId='';await openChat(id);}else{drawMessages();drawAttachments();poll();}}catch(e){error(`无法连接本地服务：${e.message}`);drawMessages();}
  }
  async function prepareTask(text){await render();if(sending||chat?.status==='running'){error('当前对话仍在回复，请停止或等待完成后再开始。');return;}newChat();$('#chatText').value=text;draft=text;setMode('task');}
  async function prepareContext(text){await render();if(sending||chat?.status==='running'){error('请等待当前回复完成后再带入工具结果。');return;}newChat();$('#chatText').value=text;draft=text;setMode('chat');}
  document.addEventListener('gongming:view-changed',()=>{if(document.body.dataset.view!=='chat')stopPoll();else poll();});
  document.addEventListener('keydown',event=>{if(event.isComposing||document.querySelector('dialog[open]'))return;const edit=event.target.closest('input,textarea,[contenteditable=true]');if((event.ctrlKey||event.metaKey)&&event.shiftKey&&event.key.toLowerCase()==='o'){event.preventDefault();window.Gongming?.openView('chat');newChat();}else if(event.key==='/'&&!edit&&document.body.dataset.view==='chat'){event.preventDefault();$('#chatText')?.focus();}else if((event.ctrlKey||event.metaKey)&&event.altKey&&['ArrowUp','ArrowDown'].includes(event.key)&&!sending){const index=chats.findIndex(c=>c.id===chat?.id),next=index+(event.key==='ArrowDown'?1:-1);if(chats[next]){event.preventDefault();openChat(chats[next].id);}}});
  window.ChatUI={render,refreshModels,newChat,attachJob,prepareTask,prepareContext,openDirect,createTeam,openChat};
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPoll();else if(document.body.dataset.view==='chat'){refreshModels().catch(()=>{});poll();}});
  window.addEventListener('focus',()=>{if(document.body.dataset.view==='chat')refreshModels().catch(()=>{});});
  document.addEventListener('close',()=>{if(document.body.dataset.view==='chat')refreshModels().catch(()=>{});},true);
